if (Cell.X <= GridSize.X && Cell.Y <= GridSize.Y && Cell.Z <= GridSize.Z)
{
    if (Filter.bWalls)
    {
        for (EStructuralWallPosition Side : {Left, Right, Front, Back})
        {
            if (AActor* Wall = NativeGetWallActor(Cell, Side)) { Out.Walls.Add({Wall, Cell, Side}); }  // 0x18-byte entries (native 0x141c81c00)
        }
    }
    if (Filter.bFloors)
    {
        if (Filter.bIncludeTopFloor)
        {
            FIntVector Above = Cell; Above.Z += 1;
            if (AActor* Top = NativeGetFloorActor(Above)) { Out.Floors.Add({Top, Cell, EStructuralFloorPosition::Top}); }
        }
        if (AActor* Bottom = NativeGetFloorActor(Cell)) { Out.Floors.Add({Bottom, Cell, EStructuralFloorPosition::Bottom}); }  // native 0x141c81b50
    }
    if (Filter.bExtras)
    {
        if (AActor* Extra = NativeGetExtraActorAtCell(Cell)) { Out.Extras.Add({Extra, Cell}); }  // 0x14-byte entries (native 0x141c81ac0)
    }
}
return Out.Walls.Num() > 0 || Out.Floors.Num() > 0 || Out.Extras.Num() > 0;
